import Foundation

/// QuoteStore without persistence, for previews and tests.
@MainActor
final class InMemoryQuoteStore: QuoteStore {
    private var storage: [BookQuote]
    private let now: @MainActor () -> Date
    private let broadcaster = QuoteBroadcaster()

    init(quotes: [BookQuote] = [], now: @escaping @MainActor () -> Date = { .now }) {
        self.storage = quotes
        self.now = now
    }

    func quotes(ofBook bookID: UUID) -> AsyncThrowingStream<[BookQuote], any Error> {
        broadcaster.makeStream(bookID: bookID, initial: .success(list(ofBook: bookID)))
    }

    func addQuote(text: String, toBook bookID: UUID) async throws -> BookQuote {
        let normalized = try QuoteText.normalized(text)
        let quote = BookQuote(id: UUID(), text: normalized, bookID: bookID, createdAt: now())
        storage.append(quote)
        broadcaster.publish(bookID: bookID) { .success(list(ofBook: bookID)) }
        return quote
    }

    func deleteQuote(id: UUID) async throws {
        guard let index = storage.firstIndex(where: { $0.id == id }) else { return }
        let removed = storage.remove(at: index)
        broadcaster.publish(bookID: removed.bookID) { .success(list(ofBook: removed.bookID)) }
    }

    private func list(ofBook bookID: UUID) -> [BookQuote] {
        storage
            .filter { $0.bookID == bookID }
            .sorted { $0.createdAt > $1.createdAt }
    }
}
