            Issue.record("The stream should end with an error")
        } catch {}
        #expect(received == [[]])
    }

    @Test func repeatedListIsNotSentAgain() async {
        let observers = QuoteListObservers()
        let book = UUID()
        let stream = observers.makeStream(bookID: book, initial: .success([]))
        var received: [[BookQuote]] = []
        do {
            for try await quotes in stream {
                received.append(quotes)
                observers.publish(bookID: book, .success([]))
                observers.publish(bookID: book, .failure(TestError()))
            }
        } catch {}
        #expect(received == [[]])
    }

    @Test func observerIsRemovedWhenStreamEnds() async {
        let observers = QuoteListObservers()
        let book = UUID()
        do {
            let stream = observers.makeStream(bookID: book, initial: .success([]))
            for try await _ in stream { break }
        } catch {}
        for _ in 0..<100 where observers.observedBookIDs.contains(book) {
            await Task.yield()
        }
        #expect(!observers.observedBookIDs.contains(book))
    }
