### `QuoteStore.swift`
```swift
import Foundation

/// The only way screens read and change quotes.
@MainActor
protocol QuoteStore: AnyObject {
    /// Quotes of one book, newest first; quotes with the same `createdAt` come in no fixed order.
    /// Emits the current list right away, then a new list whenever that book's quotes change,
    /// whoever made the change. Never yields a list equal to the last one it yielded;
    /// intermediate lists may be skipped.
    func quotes(forBook bookID: UUID) -> AsyncThrowingStream<[BookQuote], any Error>

    /// Trims whitespace; throws `QuoteStoreError.emptyText` for blank text.
    @discardableResult
    func addQuote(text: String, toBook bookID: UUID) async throws -> BookQuote

    /// Does nothing if the quote is already gone.
    func deleteQuote(id: BookQuote.ID) async throws
}

nonisolated enum QuoteStoreError: Error, Equatable {
    case emptyText
}

/// Text rules shared by every store implementation.
nonisolated enum QuoteText {
    static func normalized(_ raw: String) throws -> String {
        let text = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty else { throw QuoteStoreError.emptyText }
        return text
    }
}
```

### `QuoteListObservers.swift`
```swift
import Foundation

/// Open quote-list streams of one store. Stores call `publish` after each change.
@MainActor
final class QuoteListObservers {
    typealias Stream = AsyncThrowingStream<[BookQuote], any Error>

    private struct Observer {
        let bookID: UUID
        let continuation: Stream.Continuation
        var lastSent: [BookQuote]
    }

    private var observers: [UUID: Observer] = [:]

    var observedBookIDs: Set<UUID> {
        Set(observers.values.map(\.bookID))
    }

    func makeStream(bookID: UUID, initial: Result<[BookQuote], any Error>) -> Stream {
        // Screens only need the latest list, so older undelivered lists are dropped.
        let (stream, continuation) = Stream.makeStream(bufferingPolicy: .bufferingNewest(1))
        let quotes: [BookQuote]
        switch initial {
        case .success(let value):
            quotes = value
        case .failure(let error):
            continuation.finish(throwing: error)
            return stream
        }
        continuation.yield(quotes)
        let token = UUID()
        observers[token] = Observer(bookID: bookID, continuation: continuation, lastSent: quotes)
        continuation.onTermination = { [weak self] _ in
            Task { @MainActor in self?.observers[token] = nil }
        }
        return stream
    }

    func publish(bookID: UUID, _ result: Result<[BookQuote], any Error>) {
        for (token, observer) in observers where observer.bookID == bookID {
            switch result {
            case .success(let quotes):
                guard quotes != observer.lastSent else { continue }
                observer.continuation.yield(quotes)
                observers[token]?.lastSent = quotes
            case .failure(let error):
                observer.continuation.finish(throwing: error)
                observers[token] = nil
            }
        }
    }
}
```

### `SwiftDataQuoteStore.swift`
```swift
import Foundation
import SwiftData

@MainActor
final class SwiftDataQuoteStore: QuoteStore {
    private let container: ModelContainer
    private let context: ModelContext
    private let now: () -> Date
    private let observers = QuoteListObservers()

    init(container: ModelContainer, now: @escaping () -> Date = { .now }) {
        // A ModelContext does not reliably keep its container alive.
        self.container = container
        self.now = now
        // Own context without autosave: a failed write is rolled back here
        // and never touches unsaved changes of other screens in mainContext.
        context = ModelContext(container)
        context.autosaveEnabled = false
        observeSaves()
    }

    func quotes(forBook bookID: UUID) -> AsyncThrowingStream<[BookQuote], any Error> {
        observers.makeStream(bookID: bookID, initial: Result { try fetchQuotes(bookID: bookID) })
    }

    @discardableResult
    func addQuote(text: String, toBook bookID: UUID) async throws -> BookQuote {
        let quote = Quote(id: UUID(), text: try QuoteText.normalized(text), bookID: bookID, createdAt: now())
        context.insert(quote)
        try saveOrRollback()
        publishChanges(forBooks: [bookID])
        return BookQuote(quote)
    }

    func deleteQuote(id: BookQuote.ID) async throws {
        let quoteID = id
        var descriptor = FetchDescriptor<Quote>(predicate: #Predicate { $0.id == quoteID })
        descriptor.fetchLimit = 1
        guard let quote = try context.fetch(descriptor).first else { return }
        let bookID = quote.bookID
        context.delete(quote)
        try saveOrRollback()
        publishChanges(forBooks: [bookID])
    }

    /// Saves made anywhere on this container (other screens, other contexts) refresh open lists.
    /// Our own saves arrive here too; QuoteListObservers drops the repeated list.
    private func observeSaves() {
        // Never removed: the store lives as long as the app, and after it is gone the block does nothing.
        _ = NotificationCenter.default.addObserver(
            forName: ModelContext.didSave, object: nil, queue: .main
        ) { [weak self] notification in
            let savedContainer = (notification.object as? ModelContext)?.container
            // Safe: queue .main delivers this block on the main thread.
            MainActor.assumeIsolated {
                guard let self, savedContainer === self.container else { return }
                self.publishChanges(forBooks: self.observers.observedBookIDs)
            }
        }
    }

    private func fetchQuotes(bookID: UUID) throws -> [BookQuote] {
        let descriptor = FetchDescriptor<Quote>(
            predicate: #Predicate { $0.bookID == bookID },
            sortBy: [SortDescriptor(\.createdAt, order: .reverse)]
        )
        return try context.fetch(descriptor).map { BookQuote($0) }
    }

    private func saveOrRollback() throws {
        do {
            try context.save()
        } catch {
            context.rollback()
            throw error
        }
    }

    private func publishChanges(forBooks bookIDs: Set<UUID>) {
        for bookID in bookIDs.intersection(observers.observedBookIDs) {
            observers.publish(bookID: bookID, Result { try fetchQuotes(bookID: bookID) })
        }
    }
}

private extension BookQuote {
    init(_ model: Quote) {
        self.init(id: model.id, bookID: model.bookID, text: model.text, createdAt: model.createdAt)
    }
}
```

### `InMemoryQuoteStore.swift` (для превью и тестов)
```swift
import Foundation

@MainActor
final class InMemoryQuoteStore: QuoteStore {
    private var storage: [BookQuote]
    private let now: () -> Date
    private let observers = QuoteListObservers()

    init(quotes: [BookQuote] = [], now: @escaping () -> Date = { .now }) {
        storage = quotes
        self.now = now
    }

    func quotes(forBook bookID: UUID) -> AsyncThrowingStream<[BookQuote], any Error> {
        observers.makeStream(bookID: bookID, initial: .success(list(bookID)))
    }

    @discardableResult
    func addQuote(text: String, toBook bookID: UUID) async throws -> BookQuote {
        let quote = BookQuote(id: UUID(), bookID: bookID, text: try QuoteText.normalized(text), createdAt: now())
        storage.append(quote)
        observers.publish(bookID: bookID, .success(list(bookID)))
        return quote
    }

    func deleteQuote(id: BookQuote.ID) async throws {
        guard let index = storage.firstIndex(where: { $0.id == id }) else { return }
        let removed = storage.remove(at: index)
        observers.publish(bookID: removed.bookID, .success(list(removed.bookID)))
    }

    private func list(_ bookID: UUID) -> [BookQuote] {
        storage.filter { $0.bookID == bookID }.sorted { $0.createdAt > $1.createdAt }
    }
}
```

