```swift
import Foundation
import Observation

@Observable
final class BookQuotesModel {
    private(set) var quotes: [BookQuote] = []
    private(set) var error: (any Error)?
    private let store: any QuoteStore

    init(store: any QuoteStore) {
        self.store = store
    }

    /// Call from `.task(id: bookID)`: restarts when the book changes, ends with the screen.
    func observe(bookID: UUID) async {
        quotes = []
        error = nil
        do {
            for try await quotes in store.quotes(forBook: bookID) {
                self.quotes = quotes
            }
        } catch {
            if !Task.isCancelled { self.error = error }
        }
    }

    func add(_ text: String, toBook bookID: UUID) async {
        do { try await store.addQuote(text: text, toBook: bookID) } catch { self.error = error }
    }

    func delete(_ quote: BookQuote) async {
        do { try await store.deleteQuote(id: quote.id) } catch { self.error = error }
    }
}
