### 2. `CoverFiles.swift` — файлы на диске, вся тяжёлая работа вне главного потока

```swift
import ImageIO
import UIKit
import UniformTypeIdentifiers

/// Pixel sizes and quality for the two stored versions of a cover.
nonisolated enum CoverVariant: String, CaseIterable, Sendable {
    /// Library row, sized for the largest capped row cover at @3x.
    case thumbnail = "thumb"
    /// Book screen.
    case full

    var maxPixelSize: CGFloat {
        switch self {
        case .thumbnail: 360
        case .full: 1200
        }
    }

    var compressionQuality: Double {
        switch self {
        case .thumbnail: 0.7
        case .full: 0.75
        }
    }
}

/// Cover files in one directory. All work runs off the main thread.
nonisolated struct CoverFiles: Sendable {
    enum Failure: Error {
        case emptyImage
        case encodingFailed
    }

    /// Application Support, not Caches: covers are user data and must survive storage pressure.
    static let standard = CoverFiles(
        directory: URL.applicationSupportDirectory.appending(path: "Covers", directoryHint: .isDirectory))

    let directory: URL

    func url(for id: UUID, _ variant: CoverVariant) -> URL {
        directory.appending(path: "\(id.uuidString)-\(variant.rawValue)", directoryHint: .notDirectory)
    }

    /// Downscales the camera photo and writes both variants. On failure no files are left behind.
    @concurrent func write(_ photo: UIImage, id: UUID) async throws {
        do {
            try autoreleasepool {
                try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
                let full = try Self.downscaled(photo, maxPixelSize: CoverVariant.full.maxPixelSize)
                let thumbnail = try Self.downscaled(full, maxPixelSize: CoverVariant.thumbnail.maxPixelSize)
                try Self.encoded(full, quality: CoverVariant.full.compressionQuality)
                    .write(to: url(for: id, .full), options: .atomic)
                try Self.encoded(thumbnail, quality: CoverVariant.thumbnail.compressionQuality)
                    .write(to: url(for: id, .thumbnail), options: .atomic)
            }
        } catch {
            removeFiles(for: [id])
            throw error
        }
    }

    /// Decodes ahead of display so scrolling never decodes on the main thread.
    @concurrent func image(for id: UUID, _ variant: CoverVariant) async -> UIImage? {
        guard let source = CGImageSourceCreateWithURL(url(for: id, variant) as CFURL, nil),
              let cgImage = CGImageSourceCreateImageAtIndex(
                  source, 0, [kCGImageSourceShouldCacheImmediately: true] as CFDictionary)
        else { return nil }
        return UIImage(cgImage: cgImage)
    }

    /// Cover identifiers that have files. Files with other names are ignored and never deleted.
    @concurrent func storedIDs() async -> Set<UUID> {
        let names = (try? FileManager.default.contentsOfDirectory(atPath: directory.path(percentEncoded: false))) ?? []
        return Set(names.compactMap { UUID(uuidString: String($0.prefix(36))) })
    }

    @concurrent func delete(_ ids: [UUID]) async {
        removeFiles(for: ids)
    }

    private func removeFiles(for ids: [UUID]) {
        for id in ids {
            for variant in CoverVariant.allCases {
                try? FileManager.default.removeItem(at: url(for: id, variant))
            }
        }
    }

    /// Draws through UIKit so the camera's orientation is applied to the pixels; EXIF and GPS are dropped.
    private static func downscaled(_ image: UIImage, maxPixelSize: CGFloat) throws -> UIImage {
        let width = image.size.width * image.scale
        let height = image.size.height * image.scale
        guard width >= 1, height >= 1 else { throw Failure.emptyImage }
        let factor = min(1, maxPixelSize / max(width, height))
        let size = CGSize(width: max(1, (width * factor).rounded()), height: max(1, (height * factor).rounded()))
        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        format.preferredRange = .standard
        return UIGraphicsImageRenderer(size: size, format: format).image { _ in
            image.draw(in: CGRect(origin: .zero, size: size))
        }
    }

    /// HEIC is about half the size of JPEG at the same quality; JPEG is the fallback.
    private static func encoded(_ image: UIImage, quality: Double) throws -> Data {
        if let cgImage = image.cgImage {
            let data = NSMutableData()
            if let destination = CGImageDestinationCreateWithData(
                data as CFMutableData, UTType.heic.identifier as CFString, 1, nil) {
                CGImageDestinationAddImage(
                    destination, cgImage, [kCGImageDestinationLossyCompressionQuality: quality] as CFDictionary)
                if CGImageDestinationFinalize(destination) { return data as Data }
            }
        }
        guard let jpeg = image.jpegData(compressionQuality: quality) else { throw Failure.encodingFailed }
        return jpeg
    }
}
```

### 3. `CoverStore.swift` — единая точка работы с обложками

```swift
import SwiftData
import UIKit

/// The only entry point for reading and changing covers.
///
/// File lifetime rule: files are written before a Book points at them, and they are deleted only
/// by `removeOrphanedFiles`, once per launch. Replacing or removing a cover never deletes files
/// mid-session, so undo can always bring back a cover whose files still exist.
@MainActor
final class CoverStore {
    static let shared = CoverStore(files: .standard)

    private let files: CoverFiles
    private let cache = NSCache<NSString, UIImage>()
    /// Covers whose files are being written and that no Book references yet.
    private var pendingIDs: Set<UUID> = []
    private var hasSwept = false

    init(files: CoverFiles, cacheLimit: Int = 60 * 1024 * 1024) {
        self.files = files
        // About 150 list thumbnails plus a few book-screen covers; NSCache also evicts on memory warnings.
        cache.totalCostLimit = cacheLimit
    }

    func cachedImage(for id: UUID, _ variant: CoverVariant) -> UIImage? {
        cache.object(forKey: key(id, variant))
    }

    func image(for id: UUID, _ variant: CoverVariant) async -> UIImage? {
        if let cached = cachedImage(for: id, variant) { return cached }
        guard let image = await files.image(for: id, variant) else { return nil }
        cache.setObject(image, forKey: key(id, variant), cost: Self.memoryCost(of: image))
        return image
    }

    /// Saves a camera photo as the book's cover. The previous cover's files go at the next launch sweep.
    func setCover(_ photo: UIImage, for book: Book) async throws {
        let newID = UUID()
        pendingIDs.insert(newID)
        defer { pendingIDs.remove(newID) }

        try await files.write(photo, id: newID)
        // The book may have been deleted while the photo was processed; the sweep frees the files.
        guard let context = book.modelContext, !book.isDeleted else { return }
        let oldID = book.coverID
        book.coverID = newID
        do {
            try context.save()
        } catch {
            book.coverID = oldID
            throw error
        }
    }

    func removeCover(from book: Book) throws {
        guard let oldID = book.coverID, let context = book.modelContext else { return }
        book.coverID = nil
        do {
            try context.save()
        } catch {
            book.coverID = oldID
            throw error
        }
    }

    /// Deletes files no book points at: replaced or removed covers, deleted books, interrupted saves.
    /// Runs once per process, however many windows call it.
    func removeOrphanedFiles(in context: ModelContext) async {
        guard !hasSwept else { return }
        hasSwept = true

        let stored = await files.storedIDs()
        guard !stored.isEmpty else { return }
        var descriptor = FetchDescriptor<Book>()
        descriptor.propertiesToFetch = [\.coverID]
        // No books next to cover files more likely means a store that failed to open than an empty
        // library; keeping extra files is cheaper than losing every cover.
        guard let books = try? context.fetch(descriptor), !books.isEmpty else { return }
        // Decided in one main-actor step: a save that starts later writes files not listed in `stored`.
        let referenced = Set(books.compactMap(\.coverID))
        let orphans = stored.subtracting(referenced).subtracting(pendingIDs)
        guard !orphans.isEmpty else { return }
        await files.delete(Array(orphans))
    }

    private func key(_ id: UUID, _ variant: CoverVariant) -> NSString {
        "\(id.uuidString)-\(variant.rawValue)" as NSString
    }

    private static func memoryCost(of image: UIImage) -> Int {
        Int(image.size.width * image.scale * image.size.height * image.scale) * 4
    }
}
```

### 4. `CoverImageView.swift` — показ обложки и заглушки

```swift
import SwiftUI

/// A book cover at 2:3 proportions; set its width with `.frame(width:)`.
struct CoverImageView: View {
    let coverID: UUID?
    let variant: CoverVariant
    var cornerRadius: CGFloat = 4

    @State private var loaded: LoadedCover?

    var body: some View {
        Color.clear
            .aspectRatio(2 / 3, contentMode: .fit)
            .overlay {
                if let image = displayedImage {
                    Image(uiImage: image)
                        .resizable()
                        .scaledToFill()
                } else {
                    CoverPlaceholder()
                }
            }
            .clipShape(.rect(cornerRadius: cornerRadius))
            .task(id: coverID) {
                guard let coverID else { return }
                if let image = await CoverStore.shared.image(for: coverID, variant) {
                    loaded = LoadedCover(id: coverID, image: image)
                }
            }
            // Off-screen rows must not pin decoded images outside the cache's memory limit.
            .onDisappear { loaded = nil }
    }

    private var displayedImage: UIImage? {
        guard let coverID else { return nil }
        if let loaded, loaded.id == coverID { return loaded.image }
        // Cache hits show on the first frame, so scrolling back never flashes the placeholder.
        if let cached = CoverStore.shared.cachedImage(for: coverID, variant) { return cached }
        // While the full cover decodes, show the thumbnail the list has most likely loaded already.
        return variant == .full ? CoverStore.shared.cachedImage(for: coverID, .thumbnail) : nil
    }
}

private struct LoadedCover {
    let id: UUID
    let image: UIImage
}

struct CoverPlaceholder: View {
    var body: some View {
        Rectangle()
            .fill(.quaternary)
            .overlay {
                Image(systemName: "book.closed")
                    .imageScale(.large)
                    .foregroundStyle(.secondary)
            }
    }
}
```

### 5. `CameraPicker.swift` — системная камера

```swift
import SwiftUI
import UIKit

struct CameraPicker: UIViewControllerRepresentable {
    let onCapture: (UIImage) -> Void
    @Environment(\.dismiss) private var dismiss

    func makeCoordinator() -> Coordinator { Coordinator(parent: self) }

    func makeUIViewController(context: Context) -> UIImagePickerController {
        let picker = UIImagePickerController()
        picker.sourceType = .camera
        picker.cameraCaptureMode = .photo
        // The built-in crop is square, which does not fit book covers.
        picker.allowsEditing = false
        picker.delegate = context.coordinator
        return picker
    }

    func updateUIViewController(_ picker: UIImagePickerController, context: Context) {
        context.coordinator.parent = self
    }

    final class Coordinator: NSObject, UIImagePickerControllerDelegate, UINavigationControllerDelegate {
        var parent: CameraPicker

        init(parent: CameraPicker) { self.parent = parent }

        func imagePickerController(
            _ picker: UIImagePickerController,
            didFinishPickingMediaWithInfo info: [UIImagePickerController.InfoKey: Any]
        ) {
            if let photo = info[.originalImage] as? UIImage {
                parent.onCapture(photo)
            }
            parent.dismiss()
        }

        func imagePickerControllerDidCancel(_ picker: UIImagePickerController) {
            parent.dismiss()
        }
    }
}
```

### 6. `BookCoverSection.swift` — блок обложки на экране книги

```swift
import AVFoundation
import SwiftUI

struct BookCoverSection: View {
    let book: Book

    @State private var isShowingCamera = false
    @State private var isConfirmingRemoval = false
    @State private var isSaving = false
    @State private var problem: CoverProblem?
    @Environment(\.openURL) private var openURL

    var body: some View {
        VStack(spacing: 12) {
            CoverImageView(coverID: book.coverID, variant: .full, cornerRadius: 8)
                .frame(width: 180)
                .overlay {
                    if isSaving {
                        ProgressView()
                            .controlSize(.large)
                            .frame(maxWidth: .infinity, maxHeight: .infinity)
                            .background(.ultraThinMaterial, in: .rect(cornerRadius: 8))
                    }
                }
                .shadow(color: .black.opacity(0.15), radius: 6, y: 3)
                .accessibilityElement(children: .ignore)
                .accessibilityAddTraits(.isImage)
                .accessibilityLabel(coverAccessibilityLabel)

            if book.coverID == nil {
                Button("Сфотографировать обложку", systemImage: "camera") {
                    Task { await openCamera() }
                }
                .disabled(isSaving)
            } else {
                Menu("Обложка", systemImage: "photo") {
                    Button("Переснять", systemImage: "camera") {
                        Task { await openCamera() }
                    }
                    Button("Удалить обложку", systemImage: "trash", role: .destructive) {
                        isConfirmingRemoval = true
                    }
                }
                .disabled(isSaving)
            }
        }
        .fullScreenCover(isPresented: $isShowingCamera) {
            CameraPicker { save($0) }
                .ignoresSafeArea()
        }
        .confirmationDialog("Удалить обложку?", isPresented: $isConfirmingRemoval, titleVisibility: .visible) {
            Button("Удалить", role: .destructive) { remove() }
        }
        .alert(problem?.title ?? "", isPresented: isShowingProblem, presenting: problem) { problem in
            if problem == .cameraDenied, let url = URL(string: UIApplication.openSettingsURLString) {
                Button("Открыть настройки") { openURL(url) }
            }
            Button("OK", role: .cancel) {}
        } message: { problem in
            Text(problem.message)
        }
    }

    private var coverAccessibilityLabel: String {
        if isSaving { return "Сохраняю обложку" }
        return book.coverID == nil ? "Обложки нет" : "Обложка книги «\(book.title)»"
    }

    private var isShowingProblem: Binding<Bool> {
        Binding(get: { problem != nil }, set: { if !$0 { problem = nil } })
    }

    private func openCamera() async {
        guard UIImagePickerController.isSourceTypeAvailable(.camera) else {
            problem = .cameraUnavailable
            return
        }
        switch AVCaptureDevice.authorizationStatus(for: .video) {
        case .authorized:
            isShowingCamera = true
        case .notDetermined:
            if await AVCaptureDevice.requestAccess(for: .video) {
                isShowingCamera = true
            } else {
                problem = .cameraDenied
            }
        case .restricted:
            problem = .cameraRestricted
        default:
            problem = .cameraDenied
        }
    }

    /// The save keeps running if the user leaves the screen; the book gets its cover either way.
    private func save(_ photo: UIImage) {
        isSaving = true
        Task {
            defer { isSaving = false }
            do {
                try await CoverStore.shared.setCover(photo, for: book)
            } catch {
                problem = .saveFailed
            }
        }
    }

    private func remove() {
        do {
            try CoverStore.shared.removeCover(from: book)
        } catch {
            problem = .saveFailed
        }
    }
}

private enum CoverProblem {
    case cameraUnavailable
    case cameraDenied
    case cameraRestricted
    case saveFailed

    var title: String {
        switch self {
        case .cameraUnavailable: "Камера недоступна"
        case .cameraDenied: "Нет доступа к камере"
        case .cameraRestricted: "Камера ограничена"
        case .saveFailed: "Не удалось изменить обложку"
        }
    }

    var message: String {
        switch self {
        case .cameraUnavailable: "На этом устройстве нельзя сделать снимок."
        case .cameraDenied: "Разрешите Slumpy доступ к камере в Настройках, чтобы сфотографировать обложку."
        case .cameraRestricted: "Камера отключена ограничениями на этом устройстве, например Экранным временем."
        case .saveFailed: "Попробуйте ещё раз."
        }
    }
}
```

