    }
}

struct LibraryView: View {
    @Query(sort: \Book.addedAt, order: .reverse) private var books: [Book]

    var body: some View {
        NavigationStack {
            List(books) { book in
                NavigationLink(value: book) { BookRow(book: book) }
            }
            .navigationTitle("Библиотека")
            .navigationDestination(for: Book.self) { BookDetailView(book: $0) }
        }
    }
}

struct BookDetailView: View {
    let book: Book

    var body: some View {
        ScrollView {
            VStack(spacing: 16) {
                BookCoverSection(book: book)
                Text(book.title).font(.title2.bold()).multilineTextAlignment(.center)
                Text(book.author).foregroundStyle(.secondary).multilineTextAlignment(.center)
            }
            .padding()
        }
        .navigationBarTitleDisplayMode(.inline)
    }
}

private struct OrphanedCoverCleanup: ViewModifier {
    @Environment(\.modelContext) private var modelContext

    func body(content: Content) -> some View {
        content.task {
            // Let launch finish first; the sweep is not urgent.
            try? await Task.sleep(for: .seconds(3))
            await CoverStore.shared.removeOrphanedFiles(in: modelContext)
        }
    }
}

extension View {
    func removesOrphanedCovers() -> some View { modifier(OrphanedCoverCleanup()) }
}
