### 9. Тесты `CoverStoreTests.swift`

```swift
import SwiftData
import Testing
import UIKit
@testable import Slumpy

@MainActor
struct CoverStoreTests {
    let files = CoverFiles(
        directory: FileManager.default.temporaryDirectory.appending(path: UUID().uuidString, directoryHint: .isDirectory))
    let container: ModelContainer

    init() throws {
        container = try ModelContainer(for: Book.self, configurations: ModelConfiguration(isStoredInMemoryOnly: true))
    }

    @Test func sweepDeletesOnlyUnreferencedCovers() async throws {
        let store = CoverStore(files: files)
        let book = Book(title: "Kept", author: "A")
        container.mainContext.insert(book)
        try await store.setCover(try photo(), for: book)
        try await files.write(try photo(), id: UUID())

        await store.removeOrphanedFiles(in: container.mainContext)

        let remaining = await files.storedIDs()
        #expect(remaining == [try #require(book.coverID)])
    }

    @Test func replacedCoverStaysUntilSweep() async throws {
        let store = CoverStore(files: files)
        let book = Book(title: "Book", author: "A")
        container.mainContext.insert(book)
        try await store.setCover(try photo(), for: book)
        let oldID = try #require(book.coverID)
        try await store.setCover(try photo(), for: book)
        let newID = try #require(book.coverID)

        let beforeSweep = await files.storedIDs()
        #expect(beforeSweep == [oldID, newID])
        await store.removeOrphanedFiles(in: container.mainContext)
        let afterSweep = await files.storedIDs()
        #expect(afterSweep == [newID])
    }

    @Test func sweepDeletesNothingWhenThereAreNoBooks() async throws {
        let store = CoverStore(files: files)
        let id = UUID()
        try await files.write(try photo(), id: id)

        await store.removeOrphanedFiles(in: container.mainContext)

        let remaining = await files.storedIDs()
        #expect(remaining == [id])
    }

    @Test func writeAppliesCameraOrientationAndDownscales() async throws {
        let id = UUID()
        try await files.write(try photo(width: 4000, height: 3000, orientation: .right), id: id)

        let full = try #require(await files.image(for: id, .full))
        let thumbnail = try #require(await files.image(for: id, .thumbnail))
        #expect(full.size == CGSize(width: 900, height: 1200))
        #expect(thumbnail.size == CGSize(width: 270, height: 360))
    }

    @Test func failedWriteLeavesNoFiles() async throws {
        await #expect(throws: CoverFiles.Failure.self) {
            try await files.write(UIImage(), id: UUID())
        }
        let remaining = await files.storedIDs()
        #expect(remaining.isEmpty)
    }

    private func photo(width: Int = 400, height: Int = 300, orientation: UIImage.Orientation = .up) throws -> UIImage {
        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        let size = CGSize(width: width, height: height)
        let image = UIGraphicsImageRenderer(size: size, format: format).image { context in
            UIColor.systemTeal.setFill()
            context.fill(CGRect(origin: .zero, size: size))
        }
        return UIImage(cgImage: try #require(image.cgImage), scale: 1, orientation: orientation)
    }
}
