private struct OrphanedCoverCleanup: ViewModifier {
    @Environment(\.modelContext) private var modelContext

    func body(content: Content) -> some View {
        content.task {
            // Let launch finish first; the sweep is not urgent.
            try? await Task.sleep(for: .seconds(3))
            await CoverStore.shared.removeOrphanedFiles(in: modelContext)
        }
    }
}

extension View {
    func removesOrphanedCovers() -> some View { modifier(OrphanedCoverCleanup()) }
}
```

