### `CoverImageProcessor.swift`

```swift
import UIKit

/// Turns a camera photo into the two stored JPEGs and decodes them back, off the main thread.
nonisolated enum CoverImageProcessor {
    nonisolated struct Output: Sendable {
        let thumbnail: Data
        let image: Data
    }

    /// The book screen shows the cover up to 240×360 pt, which is 1080 px tall at @3x.
    static let imageMaxPixels: CGFloat = 1200
    /// A library row shows it up to 96×144 pt at the largest text size, 432 px tall at @3x.
    static let thumbnailMaxPixels: CGFloat = 440

    @concurrent
    static func makeCover(from photo: UIImage) async -> Output? {
        let image = downscaled(photo, maxPixels: imageMaxPixels)
        let thumbnail = downscaled(image, maxPixels: thumbnailMaxPixels)
        guard let imageData = image.jpegData(compressionQuality: 0.8),
              let thumbnailData = thumbnail.jpegData(compressionQuality: 0.75)
        else { return nil }
        return Output(thumbnail: thumbnailData, image: imageData)
    }

    /// Skips the work when the row that asked has already scrolled away.
    @concurrent
    static func decode(_ data: Data) async -> UIImage? {
        guard !Task.isCancelled else { return nil }
        return UIImage(data: data)?.preparingForDisplay()
    }

    /// Redraws upright at scale 1, so the result never depends on the camera's orientation flag.
    static func downscaled(_ image: UIImage, maxPixels: CGFloat) -> UIImage {
        let width = image.size.width * image.scale
        let height = image.size.height * image.scale
        let factor = min(1, maxPixels / max(width, height))
        let size = CGSize(width: (width * factor).rounded(), height: (height * factor).rounded())
        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        return UIGraphicsImageRenderer(size: size, format: format).image { _ in
            image.draw(in: CGRect(origin: .zero, size: size))
        }
    }
}
```

