### `BookCoverStore.swift`

```swift
import Foundation
import SwiftData

/// All cover writes, kept out of views so tests can cover them.
enum BookCoverStore {
    /// Re-fetches the book because it may have been deleted while the photo was processed.
    /// Returns false when the book no longer exists.
    @discardableResult
    static func replaceCover(
        ofBookWithID bookID: UUID,
        with images: CoverImageProcessor.Output,
        coverID: UUID = UUID(),
        in context: ModelContext
    ) throws -> Bool {
        var descriptor = FetchDescriptor<Book>(predicate: #Predicate { $0.id == bookID })
        descriptor.fetchLimit = 1
        guard let book = try context.fetch(descriptor).first else { return false }

        let newCover = BookCover(id: coverID, thumbnailData: images.thumbnail, imageData: images.image)
        context.insert(newCover)
        let oldCover = book.cover
        book.cover = newCover
        if let oldCover { context.delete(oldCover) }
        try save(context)
        return true
    }

    static func removeCover(from book: Book, in context: ModelContext) throws {
        guard let cover = book.cover else { return }
        book.cover = nil
        context.delete(cover)
        try save(context)
    }

    private static func save(_ context: ModelContext) throws {
        do {
            try context.save()
        } catch {
            context.rollback()
            throw error
        }
    }
}
