    var body: some View {
        CoverFrame(image: currentImage, iconFont: .largeTitle, cornerRadius: 8)
            .frame(maxWidth: 240)
            .overlay {
                if isProcessing {
                    ProgressView().controlSize(.large)
                }
            }
            .shadow(color: .black.opacity(0.15), radius: 8, y: 4)
            .accessibilityElement()
            .accessibilityLabel(cover == nil ? "Обложки нет" : "Обложка книги «\(title)»")
            .accessibilityValue(isProcessing ? "Сохраняется…" : "")
            .accessibilityAddTraits(.isImage)
            .task(id: cover?.id) { await load() }
    }

