### `CoverImageCache.swift`

```swift
import UIKit

/// Decoded list thumbnails, so scrolling back does not decode again. The system empties it under memory pressure.
final class CoverImageCache {
    static let shared = CoverImageCache()

    private let cache = NSCache<NSUUID, UIImage>()

    private init() {
        cache.totalCostLimit = 40 * 1024 * 1024
    }

    func image(for coverID: UUID) -> UIImage? {
        cache.object(forKey: coverID as NSUUID)
    }

    func insert(_ image: UIImage, for coverID: UUID) {
        let cost = image.cgImage.map { $0.bytesPerRow * $0.height } ?? 0
        cache.setObject(image, forKey: coverID as NSUUID, cost: cost)
    }
}
