/// Cover in a library row. Decodes off the main thread and reuses the shared cache.
struct BookCoverThumbnail: View {
    let cover: BookCover?

    @ScaledMetric(relativeTo: .body) private var width: CGFloat = 48
    @State private var loaded: LoadedCoverImage?

    var body: some View {
        let side = min(width, 96)
        CoverFrame(image: currentImage)
            .frame(width: side, height: side * 1.5)
            .accessibilityHidden(true)
            .task(id: cover?.id) { await load() }
    }

    private var currentImage: UIImage? {
        guard let cover else { return nil }
        if let loaded, loaded.coverID == cover.id { return loaded.image }
        return CoverImageCache.shared.image(for: cover.id)
    }

    private func load() async {
        guard let cover, currentImage == nil, let data = cover.thumbnailData else { return }
        let coverID = cover.id
        guard let image = await CoverImageProcessor.decode(data) else { return }
        CoverImageCache.shared.insert(image, for: coverID)
        loaded = LoadedCoverImage(coverID: coverID, image: image)
    }
}

/// Cover on the book screen. Shows the cached thumbnail until the full image is decoded.
struct BookCoverLarge: View {
    let cover: BookCover?
    let title: String
    let isProcessing: Bool

    @State private var loaded: LoadedCoverImage?

    var body: some View {
        CoverFrame(image: currentImage, iconFont: .largeTitle, cornerRadius: 8)
            .frame(maxWidth: 240)
            .overlay {
                if isProcessing {
                    ProgressView().controlSize(.large)
                }
            }
            .shadow(color: .black.opacity(0.15), radius: 8, y: 4)
            .accessibilityElement()
            .accessibilityLabel(cover == nil ? "Обложки нет" : "Обложка книги «\(title)»")
            .accessibilityValue(isProcessing ? "Сохраняется…" : "")
            .accessibilityAddTraits(.isImage)
            .task(id: cover?.id) { await load() }
    }

    private var currentImage: UIImage? {
        guard let cover else { return nil }
        if let loaded, loaded.coverID == cover.id { return loaded.image }
        return CoverImageCache.shared.image(for: cover.id)
    }

    private func load() async {
        guard let cover, loaded?.coverID != cover.id, let data = cover.imageData else { return }
        let coverID = cover.id
        guard let image = await CoverImageProcessor.decode(data) else { return }
        loaded = LoadedCoverImage(coverID: coverID, image: image)
    }
}
