struct BookDetailView: View {
    let book: Book

    @Environment(\.modelContext) private var modelContext
    @Environment(\.openURL) private var openURL

    @State private var isCameraPresented = false
    @State private var isSavingCover = false
    @State private var isRemoveConfirmationPresented = false
    @State private var alert: CoverAlert?

    private var isCameraAvailable: Bool {
        UIImagePickerController.isSourceTypeAvailable(.camera)
    }

    private var isAlertPresented: Binding<Bool> {
        Binding(get: { alert != nil }, set: { if !$0 { alert = nil } })
    }

    var body: some View {
        ScrollView {
            VStack(spacing: 20) {
                BookCoverLarge(cover: book.cover, title: book.title, isProcessing: isSavingCover)
                VStack(spacing: 6) {
                    Text(book.title).font(.title2.bold())
                    Text(book.author).foregroundStyle(.secondary)
                }
                .multilineTextAlignment(.center)
                ViewThatFits {
                    HStack(spacing: 12) { coverButtons }
                    VStack(spacing: 12) { coverButtons }
                }
                .disabled(isSavingCover)
            }
            .frame(maxWidth: .infinity)
            .padding()
        }
        .navigationBarTitleDisplayMode(.inline)
        .fullScreenCover(isPresented: $isCameraPresented) {
            CameraPicker { photo in
                isCameraPresented = false
                if let photo {
                    Task { await saveCover(from: photo) }
                }
            }
            .ignoresSafeArea()
        }
        .alert(Text(alert?.title ?? ""), isPresented: isAlertPresented, presenting: alert) { alert in
            switch alert {
            case .cameraDenied:
                Button("Открыть настройки") { openSettings() }
                Button("Отмена", role: .cancel) {}
            default:
                Button("OK", role: .cancel) {}
            }
        } message: { alert in
            Text(alert.message)
        }
        .confirmationDialog("Удалить обложку?", isPresented: $isRemoveConfirmationPresented, titleVisibility: .visible) {
            Button("Удалить обложку", role: .destructive) { removeCover() }
        }
    }

    @ViewBuilder private var coverButtons: some View {
        if isCameraAvailable {
            Button(
                book.cover == nil ? LocalizedStringKey("Сфотографировать обложку") : "Переснять",
                systemImage: "camera"
            ) {
                Task { await openCamera() }
            }
            .buttonStyle(.borderedProminent)
        }
        if book.cover != nil {
            Button("Удалить", systemImage: "trash", role: .destructive) {
                isRemoveConfirmationPresented = true
            }
            .buttonStyle(.bordered)
        }
    }

    private func openCamera() async {
        switch await CameraAccess.request() {
        case .granted: isCameraPresented = true
        case .declinedJustNow: break
        case .denied: alert = .cameraDenied
        case .restricted: alert = .cameraRestricted
        }
    }

    private func openSettings() {
        if let url = URL(string: UIApplication.openSettingsURLString) {
            openURL(url)
        }
    }

    private func saveCover(from photo: UIImage) async {
        isSavingCover = true
        defer { isSavingCover = false }
        let bookID = book.id
        guard let images = await CoverImageProcessor.makeCover(from: photo) else {
            alert = .saveFailed
            return
        }
        // Seed the cache so the screen goes straight from the old cover to the new one, without a placeholder.
        let coverID = UUID()
        if let thumbnail = await CoverImageProcessor.decode(images.thumbnail) {
            CoverImageCache.shared.insert(thumbnail, for: coverID)
        }
        do {
            try BookCoverStore.replaceCover(ofBookWithID: bookID, with: images, coverID: coverID, in: modelContext)
        } catch {
            alert = .saveFailed
        }
    }

    private func removeCover() {
        do {
            try BookCoverStore.removeCover(from: book, in: modelContext)
        } catch {
            alert = .removeFailed
        }
    }
}
