import SwiftUI
import UniformTypeIdentifiers

/// Sendable snapshot of one ReadingSession, so the CSV can be written off the main actor
/// (ReadingSession itself may be a non-Sendable model object).
nonisolated struct ReadingHistoryRow: Sendable, Equatable {
    let startedAt: Date
    let duration: TimeInterval
    let timeZoneIdentifier: String
    let bookTitle: String
    let bookAuthor: String
}

/// Builds the CSV text: RFC 4180 quoting, UTF-8 with BOM, CRLF line endings.
nonisolated enum ReadingHistoryCSV {
    /// Excel splits columns by the system list separator: ";" where the decimal separator is ","
    /// (Russia, most of Europe), "," elsewhere. Numbers and Google Sheets detect either.
    static var defaultDelimiter: Character {
        Locale.current.decimalSeparator == "," ? ";" : ","
    }

    static func make(rows: [ReadingHistoryRow], delimiter: Character = defaultDelimiter) -> String {
        let separator = String(delimiter)
        let header = [
            String(localized: "Начало"),
            String(localized: "Длительность, мин"),
            String(localized: "Книга"),
            String(localized: "Автор"),
        ]
        var lines = [header.map(quoted).joined(separator: separator)]

        var formatters: [String: DateFormatter] = [:]
        for row in rows.sorted(by: { $0.startedAt < $1.startedAt }) {
            let zone = TimeZone(identifier: row.timeZoneIdentifier) ?? .current
            let formatter = formatters[zone.identifier] ?? makeDateTimeFormatter(zone)
            formatters[zone.identifier] = formatter
            lines.append([
                formatter.string(from: row.startedAt),
                String(wholeMinutes(row.duration)),
                quoted(row.bookTitle),
                quoted(row.bookAuthor),
            ].joined(separator: separator))
        }
        // The BOM makes Excel read the file as UTF-8; without it Cyrillic turns into garbage.
        return "\u{FEFF}" + lines.joined(separator: "\r\n") + "\r\n"
    }

    /// Always quotes text, so commas, semicolons, quotes and line breaks stay inside one cell.
    static func quoted(_ value: String) -> String {
        var text = value
        // A cell starting with one of these is run as a formula by Excel (CSV injection).
        if let first = text.unicodeScalars.first, "=+-@\t\r".unicodeScalars.contains(first) {
            text = "'" + text
        }
        return "\"" + text.replacingOccurrences(of: "\"", with: "\"\"") + "\""
    }

    static func wholeMinutes(_ duration: TimeInterval) -> Int {
        guard duration.isFinite, duration > 0 else { return 0 }
        return Int((duration / 60).rounded())
    }

    /// "2026-10-27 21:30": Excel and Numbers recognize it as a date in any region.
    private static func makeDateTimeFormatter(_ zone: TimeZone) -> DateFormatter {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.timeZone = zone
        formatter.dateFormat = "yyyy-MM-dd HH:mm"
        return formatter
    }
}

/// The item handed to ShareLink. The file is written only when the user picks a destination.
nonisolated struct ReadingHistoryExport: Transferable, Sendable {
    let rows: [ReadingHistoryRow]
    let fileName: String

    static var transferRepresentation: some TransferRepresentation {
        FileRepresentation(exportedContentType: .commaSeparatedText) { export in
            // A fresh folder per export keeps the readable file name without collisions;
            // iOS purges the temporary directory itself.
            let folder = URL.temporaryDirectory
                .appending(path: UUID().uuidString, directoryHint: .isDirectory)
            try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
            let url = folder.appending(path: export.fileName)
            try Data(ReadingHistoryCSV.make(rows: export.rows).utf8).write(to: url, options: .atomic)
            return SentTransferredFile(url)
        }
    }

    static func fileName(for date: Date) -> String {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.dateFormat = "yyyy-MM-dd"
        return String(localized: "Slumpy — история чтения") + " " + formatter.string(from: date) + ".csv"
    }
}

extension ReadingHistoryExport {
    /// Runs on the main actor, where ReadingSession is safe to read.
    init(sessions: [ReadingSession], now: Date = .now) {
        self.init(
            rows: sessions.map {
                ReadingHistoryRow(
                    startedAt: $0.startedAt,
                    duration: $0.duration,
                    timeZoneIdentifier: $0.timeZoneIdentifier,
                    bookTitle: $0.bookTitle,
                    bookAuthor: $0.bookAuthor
                )
            },
            fileName: Self.fileName(for: now)
        )
    }
}

struct ReadingHistoryExportButton: View {
    let sessions: [ReadingSession]

    var body: some View {
        ShareLink(
            item: ReadingHistoryExport(sessions: sessions),
            preview: SharePreview("История чтения", image: Image(systemName: "tablecells"))
        ) {
            Label("Экспорт в CSV", systemImage: "square.and.arrow.up")
        }
        .disabled(sessions.isEmpty)
    }
}
```

