### `ReadingHistoryCSV.swift`

```swift
import CoreTransferable
import Foundation
import UniformTypeIdentifiers

/// Reading history as a CSV file that opens correctly in Excel and Numbers.
///
/// `nonisolated` because the share sheet writes the file off the main actor.
nonisolated struct ReadingHistoryCSV: Sendable {
    struct Row: Sendable {
        var startedAt: Date
        var duration: TimeInterval
        var timeZoneIdentifier: String
        var bookTitle: String
        var bookAuthor: String
    }

    var rows: [Row]
    /// Excel splits columns by the region's list separator: ";" where the decimal separator
    /// is "," (Russia, most of Europe), "," elsewhere. Numbers detects either.
    var delimiter: Character = Locale.current.decimalSeparator == "," ? ";" : ","
    var exportedAt: Date = .now

    var fileName: String {
        let today = Self.localDateTime(exportedAt, timeZoneIdentifier: TimeZone.current.identifier)
        return "История чтения \(today.prefix(10)).csv"
    }

    func makeText() -> String {
        let header = [
            String(localized: "Начало"),
            String(localized: "Длительность, мин"),
            String(localized: "Название"),
            String(localized: "Автор"),
        ].map(Self.quoted)

        let lines = rows.sorted { $0.startedAt < $1.startedAt }.map { row in
            [
                Self.localDateTime(row.startedAt, timeZoneIdentifier: row.timeZoneIdentifier),
                String(Self.wholeMinutes(row.duration)),
                Self.quoted(row.bookTitle),
                Self.quoted(row.bookAuthor),
            ]
        }

        // CSV standard (RFC 4180): CRLF after every record.
        return ([header] + lines)
            .map { $0.joined(separator: String(delimiter)) + "\r\n" }
            .joined()
    }

    func makeData() -> Data {
        // The byte order mark tells Excel the file is UTF-8; without it Cyrillic becomes garbage.
        Data([0xEF, 0xBB, 0xBF]) + Data(makeText().utf8)
    }

    /// Wall-clock time the reader saw, in the time zone where the session happened.
    /// Fixed "yyyy-MM-dd HH:mm" so Excel and Numbers recognize it as a date in any region.
    static func localDateTime(_ date: Date, timeZoneIdentifier: String) -> String {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone(identifier: timeZoneIdentifier) ?? .current
        let c = calendar.dateComponents([.year, .month, .day, .hour, .minute], from: date)
        return String(
            format: "%04ld-%02ld-%02ld %02ld:%02ld",
            c.year ?? 0, c.month ?? 0, c.day ?? 0, c.hour ?? 0, c.minute ?? 0
        )
    }

    /// Whole minutes, rounded to nearest. A whole number has no decimal separator to confuse Excel.
    static func wholeMinutes(_ duration: TimeInterval) -> Int {
        guard duration.isFinite, duration > 0 else { return 0 }
        return Int((min(duration, 1_000_000_000) / 60).rounded())
    }

    /// Always quoting text is valid CSV and keeps commas, semicolons, quotes and line breaks
    /// inside one cell; inner quotes are doubled. Text starting with = + - @ would run as a
    /// formula in Excel, so it gets a leading apostrophe.
    static func quoted(_ text: String) -> String {
        var safe = text
        if let first = safe.first, "=+-@\t\r".contains(first) {
            safe = "'" + safe
        }
        return "\"" + safe.replacing("\"", with: "\"\"") + "\""
    }
}

nonisolated extension ReadingHistoryCSV: Transferable {
    static var transferRepresentation: some TransferRepresentation {
        // The file is written only when the user actually picks a destination in the share sheet.
        FileRepresentation(exportedContentType: .commaSeparatedText) { csv in
            let folder = URL.temporaryDirectory
                .appending(path: "ReadingHistoryExport", directoryHint: .isDirectory)
            // Do not leave older copies of personal reading history in temporary storage.
            try? FileManager.default.removeItem(at: folder)
            try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
            let file = folder.appending(path: csv.fileName, directoryHint: .notDirectory)
            try csv.makeData().write(to: file, options: .atomic)
            return SentTransferredFile(file)
        }
    }
}
